import{_ as r,o as t,c as a,ah as i}from"./chunks/framework.Bja9t6Wf.js";const c=JSON.parse('{"title":"Recherche: Die Eurofighter-Affäre (Das teuerste Spielzeug)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/eurofighter.md","filePath":"recherche/eurofighter.md"}'),n={name:"recherche/eurofighter.md"};function s(u,e,h,l,d,o){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="recherche-die-eurofighter-affare-das-teuerste-spielzeug" tabindex="-1">Recherche: Die Eurofighter-Affäre (Das teuerste Spielzeug) <a class="header-anchor" href="#recherche-die-eurofighter-affare-das-teuerste-spielzeug" aria-label="Permalink to &quot;Recherche: Die Eurofighter-Affäre (Das teuerste Spielzeug)&quot;">​</a></h1><p>In unserer Mockumentary dient der Eurofighter-Skandal als ultimatives Beispiel für &quot;Gegengeschäfte&quot; und das, was Dr. von Zitzewitz als &quot;kreative Rüstungs-Diplomatie&quot; bezeichnet.</p><h2 id="der-kern-des-skandals" tabindex="-1">Der Kern des Skandals <a class="header-anchor" href="#der-kern-des-skandals" aria-label="Permalink to &quot;Der Kern des Skandals&quot;">​</a></h2><p>Seit 2002 beschäftigt dieser Rüstungskauf die österreichische Justiz. Es geht um 15 bis 18 Kampfflugzeuge, hunderte Millionen an Schmiergeldverdacht und ein Geflecht aus Briefkastenfirmen, das selbst Profis schwindelig macht.</p><h2 id="warum-das-fur-uns-wichtig-ist" tabindex="-1">Warum das für uns wichtig ist <a class="header-anchor" href="#warum-das-fur-uns-wichtig-ist" aria-label="Permalink to &quot;Warum das für uns wichtig ist&quot;">​</a></h2><p>Während Helmut Horten in den 30ern Kaufhäuser &quot;bereinigte&quot;, zeigt die Eurofighter-Affäre, wie man im 21. Jahrhundert hunderte Millionen Euro in &quot;Lobbying-Netzwerken&quot; verschwinden lässt, ohne dass am Ende jemand genau weiß, wohin das Geld geflogen ist.</p><h3 id="fakten-quellen" tabindex="-1">Fakten &amp; Quellen: <a class="header-anchor" href="#fakten-quellen" aria-label="Permalink to &quot;Fakten &amp; Quellen:&quot;">​</a></h3><ul><li><strong>Status:</strong> Unendliche Geschichte. Mehrere U-Ausschüsse, jahrelange Ermittlungen der WKStA.</li><li><strong>Wikipedia:</strong> <a href="https://de.wikipedia.org/wiki/Eurofighter-Aff%C3%A4re" target="_blank" rel="noreferrer">Details zum Eurofighter-Skandal</a></li><li><strong>Die Kosten:</strong> Milliarden an Steuergeldern für Jets, deren Wartung und politische Nachbehandlung.</li></ul><hr><p><em>In Teil 3 unserer Mockumentary vergleichen wir die &#39;Gegengeschäfte&#39; der Eurofighter mit den &#39;Kaufverträgen&#39; der Alsberg-Häuser.</em></p>',10)])])}const g=r(n,[["render",s]]);export{c as __pageData,g as default};
